/* WellStream Platform — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg-primary: #0D1B2A;
  --bg-secondary: #1B2838;
  --bg-card: #162032;
  --bg-card-hover: #1e2d42;
  --navy: #15295A;
  --accent-green: #6CC24A;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --text-primary: #F0F4F8;
  --text-secondary: #94A3B8;
  --text-muted: #64748B;
  --border: rgba(255,255,255,0.08);
  --border-accent: rgba(108,194,74,0.3);
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);
  --radius: 12px;
  --radius-sm: 8px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Typography ── */
h1, h2, h3, h4, h5, h6 {
  font-family: 'Space Grotesk', sans-serif;
  line-height: 1.15;
  font-weight: 700;
}

a { color: inherit; text-decoration: none; }

/* ── Header / Nav ── */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
}

.logo-mark {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-green));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 800;
  color: #fff;
  flex-shrink: 0;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-link {
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 6px;
  transition: color 0.2s, background 0.2s;
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.06); }

/* Dropdown */
.nav-dropdown { position: relative; }

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
}

.nav-dropdown-toggle::after {
  content: '▾';
  font-size: 10px;
  transition: transform 0.2s;
}

.nav-dropdown:hover .nav-dropdown-toggle::after { transform: rotate(180deg); }

.nav-dropdown-menu {
  display: none;
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 200px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px;
  box-shadow: var(--shadow-lg);
}

.nav-dropdown:hover .nav-dropdown-menu { display: block; }

.nav-dropdown-menu a {
  display: block;
  padding: 10px 14px;
  font-size: 14px;
  color: var(--text-secondary);
  border-radius: 6px;
  transition: all 0.15s;
}

.nav-dropdown-menu a:hover {
  color: var(--text-primary);
  background: rgba(255,255,255,0.06);
}

.header-ctas {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 22px;
  border-radius: 6px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 14px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0D1B2A;
}
.btn-primary:hover { background: #7dd85a; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(108,194,74,0.35); }

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid rgba(255,255,255,0.2);
}
.btn-outline:hover { border-color: rgba(255,255,255,0.4); background: rgba(255,255,255,0.05); }

.btn-blue {
  background: var(--accent-blue);
  color: #fff;
}
.btn-blue:hover { background: #00c9f0; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(0,180,216,0.35); }

.btn-lg { padding: 14px 30px; font-size: 16px; border-radius: 8px; }
.btn-sm { padding: 8px 16px; font-size: 13px; }

/* ── Page Layout ── */
.page-main { padding-top: 72px; }

.container { max-width: 1280px; margin: 0 auto; padding: 0 32px; }
.container-sm { max-width: 900px; margin: 0 auto; padding: 0 32px; }

.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }

.section-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-green);
  margin-bottom: 16px;
}

.section-title {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 680px;
}

/* ── Hero ── */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #0D1B2A 0%, #0f2240 50%, #0D1B2A 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 40%, rgba(0,180,216,0.12) 0%, transparent 60%),
    radial-gradient(ellipse 50% 40% at 20% 70%, rgba(108,194,74,0.08) 0%, transparent 50%);
  pointer-events: none;
}

/* Grid pattern overlay */
.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
  pointer-events: none;
}

.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(108,194,74,0.12);
  border: 1px solid rgba(108,194,74,0.25);
  border-radius: 100px;
  font-size: 12px;
  font-weight: 500;
  color: var(--accent-green);
  margin-bottom: 24px;
  font-family: 'JetBrains Mono', monospace;
  letter-spacing: 0.05em;
}

.hero-badge::before {
  content: '';
  width: 6px; height: 6px;
  background: var(--accent-green);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.8); }
}

.hero-title {
  font-size: clamp(32px, 4.5vw, 56px);
  font-weight: 800;
  line-height: 1.1;
  color: var(--text-primary);
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.hero-title span { color: var(--accent-blue); }

.hero-subtitle {
  font-size: 18px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 520px;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* ── Platform Ecosystem Diagram ── */
.ecosystem-diagram {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  max-width: 480px;
  margin: 0 auto;
}

.eco-center {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 120px; height: 120px;
  background: linear-gradient(135deg, var(--navy), #0D1B2A);
  border: 2px solid var(--accent-blue);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-blue);
  z-index: 3;
  box-shadow: 0 0 40px rgba(0,180,216,0.3);
}

.eco-center span { font-size: 18px; margin-bottom: 4px; }

.eco-orbit {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 320px; height: 320px;
  border: 1px dashed rgba(0,180,216,0.2);
  border-radius: 50%;
}

.eco-node {
  position: absolute;
  width: 100px; height: 80px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
  transition: all 0.3s;
  cursor: default;
}

.eco-node:hover {
  border-color: var(--accent-green);
  background: var(--bg-card-hover);
  transform: scale(1.05);
}

.eco-node .eco-icon { font-size: 20px; margin-bottom: 4px; }
.eco-node .eco-label { font-size: 10px; color: var(--text-secondary); margin-top: 2px; }

/* Positions around circle */
.eco-node-1 { top: 2%; left: 50%; transform: translateX(-50%); }
.eco-node-2 { top: 25%; right: 0%; }
.eco-node-3 { bottom: 25%; right: 0%; }
.eco-node-4 { bottom: 2%; left: 50%; transform: translateX(-50%); }
.eco-node-5 { bottom: 25%; left: 0%; }
.eco-node-6 { top: 25%; left: 0%; }

/* Connecting lines */
.eco-lines {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

/* ── Featured Product Banner ── */
.product-banner {
  background: linear-gradient(135deg, var(--navy) 0%, #0a1835 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 40px 0;
  position: relative;
  overflow: hidden;
}

.product-banner::before {
  content: '';
  position: absolute;
  right: -100px;
  top: -50px;
  width: 400px; height: 300px;
  background: radial-gradient(ellipse, rgba(0,180,216,0.15), transparent 70%);
}

.product-banner-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.product-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--accent-blue);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.product-banner h3 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
}

/* ── Use Cases ── */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.use-case-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  transition: all 0.3s;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.use-case-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--accent-green), var(--accent-blue));
  transform: scaleX(0);
  transition: transform 0.3s;
}

.use-case-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: var(--bg-card-hover);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}

.use-case-card:hover::before { transform: scaleX(1); }

.use-case-icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 20px;
}

.use-case-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 10px;
  color: var(--text-primary);
}

.use-case-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

.use-case-card .card-arrow {
  margin-top: 20px;
  font-size: 13px;
  color: var(--accent-green);
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 4px;
  opacity: 0;
  transition: opacity 0.2s;
}

.use-case-card:hover .card-arrow { opacity: 1; }

/* ── Industry Tabs ── */
.industry-tabs-container { margin-top: 64px; }

.tabs-nav {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 0;
}

.tabs-nav::-webkit-scrollbar { display: none; }

.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  font-family: 'Plus Jakarta Sans', sans-serif;
  margin-bottom: -1px;
}

.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active { color: var(--accent-green); border-bottom-color: var(--accent-green); }

.tabs-content { padding-top: 40px; }

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.tab-panel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.tab-panel-text h3 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
}

.tab-panel-text p {
  font-size: 16px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
}

.tab-features {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tab-feature-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--text-secondary);
}

.tab-feature-item::before {
  content: '';
  width: 6px; height: 6px;
  background: var(--accent-green);
  border-radius: 50%;
  flex-shrink: 0;
}

/* Visual placeholder for tab */
.tab-visual {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  aspect-ratio: 4/3;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  overflow: hidden;
}

.tab-visual::before {
  content: '';
  position: absolute;
  top: 0; right: 0;
  width: 60%; height: 40%;
  background: radial-gradient(ellipse, rgba(0,180,216,0.1), transparent 70%);
}

.mini-chart-bar {
  height: 8px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  opacity: 0.7;
}

.mini-stat {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: rgba(255,255,255,0.04);
  border-radius: 6px;
  font-size: 13px;
}

.mini-stat-value {
  font-family: 'JetBrains Mono', monospace;
  font-size: 16px;
  font-weight: 700;
  color: var(--accent-green);
}

/* ── Platform Overview Diagram (Home) ── */
.platform-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  background: var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  margin-top: 64px;
}

.pillar {
  background: var(--bg-card);
  padding: 48px 36px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  position: relative;
  overflow: hidden;
  transition: background 0.3s;
}

.pillar:hover { background: var(--bg-card-hover); }

.pillar::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transform: scaleX(0);
  transition: transform 0.3s;
}

.pillar:hover::after { transform: scaleX(1); }

.pillar-number {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--accent-blue);
  font-weight: 500;
}

.pillar-icon {
  font-size: 32px;
}

.pillar h3 {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
}

.pillar p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.65;
}

/* ── Culture Section ── */
.culture-section {
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
  position: relative;
  overflow: hidden;
}

.culture-section::before {
  content: '';
  position: absolute;
  top: -100px; right: -100px;
  width: 500px; height: 500px;
  background: radial-gradient(ellipse, rgba(108,194,74,0.08), transparent 70%);
}

.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.culture-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 40px;
}

.culture-stat {
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
}

.culture-stat-number {
  font-size: 40px;
  font-weight: 800;
  color: var(--accent-green);
  line-height: 1;
  margin-bottom: 8px;
  font-family: 'Space Grotesk', sans-serif;
}

.culture-stat-label {
  font-size: 13px;
  color: var(--text-secondary);
}

/* ── Renewables CTA ── */
.renewables-cta {
  background: linear-gradient(135deg, rgba(0,180,216,0.1) 0%, rgba(108,194,74,0.05) 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.renewables-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
}

.renewables-icons {
  display: flex;
  gap: 16px;
  font-size: 36px;
}

/* ── Footer ── */
.site-footer {
  background: #0a1520;
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 16px;
}

.footer-tagline {
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.65;
  max-width: 280px;
  margin-bottom: 24px;
}

.footer-login-links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-login-link {
  font-size: 13px;
  color: var(--text-muted);
  padding: 6px 12px;
  background: rgba(255,255,255,0.04);
  border-radius: 4px;
  transition: all 0.2s;
  display: block;
}

.footer-login-link:hover { background: rgba(255,255,255,0.08); color: var(--text-secondary); }

.footer-nav-group h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin-bottom: 16px;
  font-family: 'JetBrains Mono', monospace;
}

.footer-nav-group ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }

.footer-nav-group a {
  font-size: 14px;
  color: var(--text-muted);
  transition: color 0.2s;
}

.footer-nav-group a:hover { color: var(--text-secondary); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: var(--text-muted);
}

/* ── Page Hero (inner pages) ── */
.page-hero {
  padding: 100px 0 80px;
  background: linear-gradient(135deg, #0D1B2A 0%, #0f2240 100%);
  position: relative;
  overflow: hidden;
  text-align: center;
}

.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 50% 50%, rgba(0,180,216,0.08) 0%, transparent 60%);
}

.page-hero::after {
  content: '';
  position: absolute;
  inset: 0;
